const LOOKALIKES = [{"cat": "shape", "a": {"g": "未", "py": "wèi", "en": "not yet", "word": "未", "wordEn": "not yet", "wordId": "wei"}, "b": {"g": "末", "py": "mò", "en": "end / tip", "word": "周末", "wordEn": "weekend", "wordId": "zhoumo"}, "diff": "The two horizontal strokes swap lengths. <b>未</b>: the <b>top stroke is shorter</b> — it has not reached the end yet. <b>末</b>: the <b>top stroke is longer</b> — it reaches all the way to the end."}, {"cat": "shape", "a": {"g": "土", "py": "tǔ", "en": "earth / soil", "word": "土豆", "wordEn": "potato", "wordId": "tudou"}, "b": {"g": "士", "py": "shì", "en": "scholar / soldier", "word": "护士", "wordEn": "nurse", "wordId": "hushi"}, "diff": "Same strokes, different balance. <b>土</b> stands on a <b>long bottom stroke</b> — the ground it stands on. <b>士</b> has the <b>long stroke on top</b> and only a short base."}, {"cat": "shape", "a": {"g": "大", "py": "dà", "en": "big", "word": "大人", "wordEn": "grown-up / adult", "wordId": "daren"}, "b": {"g": "太", "py": "tài", "en": "too / very", "word": "太", "wordEn": "too / very", "wordId": "tai"}, "diff": "<b>太</b> is <b>大 plus one dot</b> underneath. No dot = big （大）. Dot added = too / very （太） — as in 太好了, “wonderful!”"}, {"cat": "shape", "a": {"g": "人", "py": "rén", "en": "person", "word": "中国人", "wordEn": "Chinese person / Chinese people", "wordId": "zhongguoren"}, "b": {"g": "入", "py": "rù", "en": "to enter", "word": "入伍", "wordEn": "to join the army; to enlist — to step into the ranks", "wordId": "ruwu119"}, "diff": "The same two strokes, leaning differently. <b>人</b> is a person walking — the long stroke steps down on the <b>left</b>. <b>入</b> tips the other way — the long stroke sweeps in from the <b>right</b>, like stepping through a door."}, {"cat": "shape", "a": {"g": "白", "py": "bái", "en": "white", "word": "白色", "wordEn": "white (the colour)", "wordId": "baise"}, "b": {"g": "日", "py": "rì", "en": "sun / day", "word": "生日", "wordEn": "birthday", "wordId": "shengri"}, "diff": "<b>白</b> is <b>日 with a small tick</b> on its top-left corner. Plain box with a middle line = 日 (sun / day). Tick on top = 白 (white)."}, {"cat": "shape", "a": {"g": "鸟", "py": "niǎo", "en": "bird", "word": "鸟", "wordEn": "bird", "wordId": "niao"}, "b": {"g": "乌", "py": "wū", "en": "black / crow", "word": "乌鸦", "wordEn": "crow", "wordId": "wuya"}, "diff": "Same bird, one stroke missing. <b>鸟</b> has a short horizontal stroke inside — its <b>eye</b>. <b>乌</b> lost the eye, which fits: it is the dark one, the crow （乌鸦） and the dark cloud （乌云）."}, {"cat": "shape", "a": {"g": "午", "py": "wǔ", "en": "noon", "word": "中午", "wordEn": "noon / midday", "wordId": "zhongwu"}, "b": {"g": "牛", "py": "niú", "en": "cow / ox", "word": "牛奶", "wordEn": "milk", "wordId": "niunai"}, "diff": "<b>牛</b> grows a horn: its <b>vertical stroke pokes out above</b> the top line. <b>午</b> keeps its vertical tucked under the top stroke — noon stays neatly under the roof."}, {"cat": "shape", "a": {"g": "己", "py": "jǐ", "en": "self", "word": "自己", "wordEn": "oneself / by oneself", "wordId": "ziji"}, "b": {"g": "已", "py": "yǐ", "en": "already", "word": "已经", "wordEn": "already", "wordId": "yijing"}, "diff": "Watch the opening on the left. <b>己</b> is <b>wide open</b> — the mouth is fully open for “self”. <b>已</b> is <b>half-closed</b>: its left side rises higher, because it is already halfway done."}, {"cat": "shape", "a": {"g": "王", "py": "wáng", "en": "king", "word": "蜂王", "wordEn": "a queen bee — the one mother of the whole hive", "wordId": "fengwang92"}, "b": {"g": "玉", "py": "yù", "en": "jade", "word": "玉兰", "wordEn": "yulan magnolia", "wordId": "yulan70"}, "diff": "<b>玉</b> is <b>王 plus one dot</b> at the lower right. Three lines on a string and no dot = a king （王）. Add the dot and the king’s treasure becomes jade （玉）."}, {"cat": "shape", "a": {"g": "木", "py": "mù", "en": "wood / tree", "word": "积木", "wordEn": "building blocks", "wordId": "jimu"}, "b": {"g": "本", "py": "běn", "en": "book; root", "word": "课本", "wordEn": "textbook", "wordId": "keben"}, "diff": "<b>本</b> is <b>木 with one short stroke</b> across its lower trunk — a mark at the <b>root</b>. That is exactly what 本 means: root, origin — and a book, the root of study."}, {"cat": "shape", "a": {"g": "干", "py": "gān", "en": "dry", "word": "干净", "wordEn": "clean", "wordId": "ganjing"}, "b": {"g": "千", "py": "qiān", "en": "thousand", "word": "千克", "wordEn": "kilogram", "wordId": "qianke"}, "diff": "The first stroke tells them apart. <b>千</b> starts with a <b>slanting sweep</b> to the left. <b>干</b> starts with a <b>flat, straight line</b> — straight and dry."}, {"cat": "shape", "a": {"g": "田", "py": "tián", "en": "field", "word": "田野", "wordEn": "fields / open countryside", "wordId": "tianye"}, "b": {"g": "由", "py": "yóu", "en": "from; free", "word": "自由泳", "wordEn": "freestyle swimming", "wordId": "ziyouyong"}, "diff": "<b>由</b> pokes through: its <b>middle vertical rises out of the box</b> at the top. <b>田</b> keeps its cross tucked safely inside the field."}, {"cat": "part", "a": {"g": "清", "py": "qīng", "en": "clear", "word": "清晨", "wordEn": "early morning", "wordId": "qingchen"}, "b": {"g": "晴", "py": "qíng", "en": "sunny / clear", "word": "晴天", "wordEn": "sunny day", "wordId": "qingtian"}, "diff": "Both carry <b>青</b> as their sound block. The left side names the family: <b>氵(water)</b> → 清， clear water. <b>日 (sun)</b> → 晴， a clear, sunny sky."}, {"cat": "part", "a": {"g": "情", "py": "qíng", "en": "feeling", "word": "热情", "wordEn": "warm-hearted / enthusiastic", "wordId": "reqing"}, "b": {"g": "请", "py": "qǐng", "en": "please; to invite", "word": "请问", "wordEn": "excuse me — may I ask…", "wordId": "qingwen"}, "diff": "Both carry <b>青</b>. <b>忄(heart)</b> → 情， feelings that live inside. <b>讠(speech)</b> → 请， “please” — feelings are felt, requests are spoken."}, {"cat": "part", "a": {"g": "洋", "py": "yáng", "en": "ocean", "word": "海洋", "wordEn": "ocean", "wordId": "haiyang"}, "b": {"g": "样", "py": "yàng", "en": "kind / pattern", "word": "一样", "wordEn": "the same", "wordId": "yiyang"}, "diff": "Both carry <b>羊 yáng</b> as their sound block. <b>氵(water)</b> → 洋， the ocean. <b>木 (wood)</b> → 样， a kind or pattern — the first samples were cut from wood."}, {"cat": "part", "a": {"g": "泡", "py": "pào", "en": "bubble; to soak", "word": "泡泡", "wordEn": "bubbles", "wordId": "paopao"}, "b": {"g": "跑", "py": "pǎo", "en": "to run", "word": "跑步", "wordEn": "to run / to jog", "wordId": "paobu"}, "diff": "Both carry <b>包 bāo</b>. <b>氵(water)</b> → 泡， bubbles in water. <b>足 (foot)</b> → 跑， to run. Water or feet — the left side decides."}, {"cat": "part", "a": {"g": "妈", "py": "mā", "en": "mum / mother", "word": "妈妈", "wordEn": "mum / mother", "wordId": "mama"}, "b": {"g": "蚂", "py": "mǎ", "en": "ant (in 蚂蚁）", "word": "蚂蚁", "wordEn": "ant", "wordId": "mayi"}, "diff": "Both carry <b>马 mǎ</b> (horse) as their sound block. <b>女 (woman)</b> → 妈， mum. <b>虫 (insect)</b> → 蚂， the ant in 蚂蚁."}, {"cat": "part", "a": {"g": "问", "py": "wèn", "en": "to ask", "word": "问题", "wordEn": "question / problem", "wordId": "wenti"}, "b": {"g": "间", "py": "jiān", "en": "room / space", "word": "房间", "wordEn": "room", "wordId": "fangjian"}, "diff": "Both live behind a <b>门 (door)</b>. A <b>口 (mouth)</b> at the door → 问， to ask. The <b>日 (sun)</b> slipping through the door → 间， the space — and the room — inside."}, {"cat": "part", "a": {"g": "猫", "py": "māo", "en": "cat", "word": "猫", "wordEn": "cat", "wordId": "mao"}, "b": {"g": "苗", "py": "miáo", "en": "seedling / sprout", "word": "疫苗", "wordEn": "vaccine", "wordId": "yimiao"}, "diff": "<b>苗</b> hides inside <b>猫</b>: animal （犭） + 苗 = the cat. On its own, 苗 is the little seedling — grass over a field （田） — the sprout in 疫苗 and 蒜苗."}, {"cat": "sound", "a": {"g": "他", "py": "tā", "en": "he / him", "word": "他们", "wordEn": "they / them", "wordId": "tamen"}, "b": {"g": "她", "py": "tā", "en": "she / her", "word": "她", "wordEn": "she / her", "wordId": "ta2"}, "diff": "They <b>sound exactly the same</b> — both tā — so your ears can’t help; only the left side tells them apart. <b>他</b> starts with 亻 (person). <b>她</b> starts with 女 (woman)."}, {"cat": "sound", "a": {"g": "是", "py": "shì", "en": "to be", "word": "是", "wordEn": "to be (am / is / are)", "wordId": "shi"}, "b": {"g": "事", "py": "shì", "en": "a thing / matter", "word": "故事", "wordEn": "story", "wordId": "gushi"}, "diff": "Both are <b>shì</b>. <b>是</b> is the linking word — “to be” （是 / 不是）. <b>事</b> names a thing that happens — a matter, a story. Look at 事： one long vertical stroke runs through it and ends in a hook."}, {"cat": "sound", "a": {"g": "在", "py": "zài", "en": "at; to be (in a place)", "word": "现在", "wordEn": "now", "wordId": "xianzai"}, "b": {"g": "再", "py": "zài", "en": "again", "word": "再见", "wordEn": "goodbye", "wordId": "zaijian"}, "diff": "Both are <b>zài</b>. <b>在</b> stands on <b>土 (earth)</b> — it is about being in a place （现在， 在家）. <b>再</b> has no earth under it — it means “again” （再见， 再来）."}, {"cat": "sound", "a": {"g": "做", "py": "zuò", "en": "to do / make", "word": "做饭", "wordEn": "to cook (a meal)", "wordId": "zuofan"}, "b": {"g": "坐", "py": "zuò", "en": "to sit", "word": "坐车", "wordEn": "to ride (a bus / car / train)", "wordId": "zuoche"}, "diff": "Both are <b>zuò</b>. <b>做</b> has 亻 — a <b>person</b> doing and making. <b>坐</b> is two people sitting on the <b>土 (ground)</b> — to sit, and to ride sitting down （坐车）."}, {"cat": "sound", "a": {"g": "向", "py": "xiàng", "en": "towards", "word": "向日葵", "wordEn": "sunflower", "wordId": "xiangrikui"}, "b": {"g": "像", "py": "xiàng", "en": "to look like; an image", "word": "雕像", "wordEn": "a statue; a sculpture", "wordId": "diaoxiang85"}, "diff": "Both are <b>xiàng</b>. <b>像</b> has 亻 — a person-like <b>image</b>: a statue or photo that looks like someone. <b>向</b> has no person — it faces a <b>direction</b>, like the sunflower （向日葵） facing the sun."}, {"cat": "sound", "a": {"g": "园", "py": "yuán", "en": "garden / park", "word": "公园", "wordEn": "park", "wordId": "gongyuan"}, "b": {"g": "圆", "py": "yuán", "en": "round", "word": "汤圆", "wordEn": "sweet glutinous rice balls", "wordId": "tangyuan"}, "diff": "Both are <b>yuán</b>. <b>园</b> is a <b>place</b> with a fence around it — a park or garden you walk in. <b>圆</b> is the <b>round shape</b> itself — round dumplings （汤圆）, a round coin."}, {"cat": "sound", "a": {"g": "蓝", "py": "lán", "en": "blue", "word": "蓝色", "wordEn": "blue (the colour)", "wordId": "lanse"}, "b": {"g": "篮", "py": "lán", "en": "basket", "word": "篮球", "wordEn": "basketball", "wordId": "lanqiu"}, "diff": "Both are <b>lán</b>. The top tells them apart: <b>艹 (grass)</b> → 蓝， blue — the colour first came from a plant. <b>竹 (bamboo)</b> → 篮， a basket woven from bamboo — the 篮 in 篮球."}, {"cat": "sound", "a": {"g": "进", "py": "jìn", "en": "to enter", "word": "进来", "wordEn": "to come in", "wordId": "jinlai"}, "b": {"g": "近", "py": "jìn", "en": "near", "word": "最近", "wordEn": "recently; lately", "wordId": "zuijin66"}, "diff": "Both are <b>jìn</b> and both walk with 辶. Inside, <b>井</b> → 进， to go in and move forward. <b>斤</b> → 近， near — close enough to reach."}, {"cat": "sound", "a": {"g": "买", "py": "mǎi", "en": "to buy", "word": "买菜", "wordEn": "to buy groceries / vegetables", "wordId": "maicai"}, "b": {"g": "卖", "py": "mài", "en": "to sell", "word": "外卖", "wordEn": "takeaway / food delivery", "wordId": "waimai"}, "diff": "Tone twins: <b>mǎi</b> (3rd tone) is to <b>buy</b>, <b>mài</b> (4th tone) is to <b>sell</b>. And 卖 is 买 with an extra cap on top — the seller adds a price on top of the goods."}];

